function Obj2000002_OnSpawn(...)
-- Constantin Ciprian Bacioiu has added init's here for Lottery!
    -- We use this to get the sum of an array of numbers! Use sumt(t) for this! 

    function sumf(a, ...) return a and a + sumf(...) or 0 end
    function sumt(t) return sumf(unpack(t)) end



    -- Phase 1: Retrieve all the waypoints from the groups and spawn the objects
    -- Phase 2: Check for interaction between Batman and lottery boxes
    -- Phase 3: Remove lottery boxes and switch to 1.
    -- Also, LUA, Y U NO HAZ SWITCH CASE LIKE C/C++?? HA?? HA???
    w_LotteryPhase = 1;
    w_LotterySpawn = true;
    w_LotteryGroupOrder = 1;



    --w_Group1SpawnPoints = {GetWaypointsInGroup(2000008)};
    w_LotteryStatus = { };
    w_LotteryObjectsID = { };

    DisableAndQuit = false;

    function w_EnableLotteryBoxGeneration( )
        w_LotteryPhase = 1;
        w_LotterySpawn = true;
        w_LotteryGroupOrder = 1;



        --w_Group1SpawnPoints = {GetWaypointsInGroup(2000008)};
        w_LotteryStatus = { };
        w_LotteryObjectsID = { };

        DisableAndQuit = false; 


        Enable(2000033);
    end;


    function w_DisableLotteryBoxGeneration( )

        for w_i4 = 1, table.getn(w_LotteryObjectsID) do
            HideObject(w_LotteryObjectsID[w_i4]);
            Disable(w_LotteryObjectsID[w_i4]);
        end;

        Wait(200);
        Disable(2000033);



    end;

w_EnableLotteryBoxGeneration( );


--Wait(4000);
--w_DisableLotteryBoxGeneration( );
end

